export const compileAllLibs = async (
		hOptions: hash = {}
		): AutoPromise<void> => {

	const [n, secs] = await compileFilesMatching('**/*.lib.civet', hOptions)
	if (n > 0) {
		LOG(`${n} libs compiled in ${secs} secs.`)
	}
	return
}

